import os, sys, csv
sys.path.insert(0, os.path.dirname(__file__)); from tools import TOOLS, contribution
ROOT = os.path.join(os.path.dirname(__file__), "..")
TIER = {"09": "A", "10": "A", "01": "A", "04": "A", "07": "A", "08": "B", "05": "B", "06": "B", "02": "B", "03": "B"}
EOL = {"01": "Play a 2.8 kHz tone from a phone speaker at 10 cm for 1 s: counter must increment; play white noise: must not.",
       "02": "Zero the plate, place a 20 kg reference weight: reading within ±0.1 kg; remove: returns to 0 ±0.05 kg; store counts/kg in EEPROM.",
       "03": "Magnet near reed: silent; magnet away 65 s: chirp; 185 s: continuous.", "04": "Flash a 1 Hz LED at the head: count = 1/s; cover with ambient light: no spurious counts.",
       "05": "Remove 5 V for 10 s: one cut of 10 s ±1 logged; restore.", "06": "Set 1:00 on each channel, check four independent rings within ±1 s.",
       "07": "Wet the plate with a drop of water for 4 s: alert; dry: clears after 2 min.", "08": "Run 10 L from a calibrated bucket: reading 10 L ±0.2 L (adjust pulses/L)."}
import trimesh
from trimesh.creation import box, cylinder
def enclosure(t, d):
    w, dd, h = t["box"]; body = box([w, dd, h]).difference(box([w - 4.8, dd - 4.8, h - 2.4]).apply_translation([0, 0, 1.2 + 0.001]))
    for c in t["cut"]:
        face, kind = c[0], c[1]
        if kind == "round": x, y, r = c[2], c[3], c[4]; cut = cylinder(radius=r, height=10, sections=24)
        elif kind == "rect": x, y, ww, hh = c[2], c[3], c[4], c[5]; cut = box([ww, hh, 10])
        else: x, y, n = c[2], c[3], c[4]; cut = None
        if face == "top":
            if kind == "slots":
                for i in range(-3, 4): body = body.difference(box([1.6, 10, 6]).apply_translation([x + i * 3.2, y, h / 2]))
            else: body = body.difference(cut.apply_translation([x, y, h / 2]))
        elif face == "side" and kind == "rect": body = body.difference(box([10, c[4], c[5]]).apply_translation([w / 2, c[2], c[3]]))
        elif face == "front" and kind == "round":
            cc = cylinder(radius=c[4], height=10, sections=24); cc.apply_transform(trimesh.transformations.rotation_matrix(1.5708, [1, 0, 0])); body = body.difference(cc.apply_translation([c[2], -dd / 2, c[3]]))
    lid = box([w - 4.4, dd - 4.4, 2.2]); body.export(os.path.join(d, "enclosure_body.stl")); lid.export(os.path.join(d, "enclosure_lid.stl")); return body.is_watertight and lid.is_watertight
idx = []; rows = []
for t in TOOLS:
    b = sum(v for _, v in t["bom"]); p = sum(v for _, v in t["proto"]); assert p <= 3000
    c, m = contribution(t["price"], b, t["gst"]); c3, m3 = contribution(t["price"], b * 1.3, t["gst"])
    d = os.path.join(ROOT, f"{t['id']}-{t['slug']}"); os.makedirs(d, exist_ok=True)
    wt = enclosure(t, d) if t["box"] else None
    first = f" The first-draft price was Rs {t['price_first']}, which made too little margin, so it was raised." if "price_first" in t else ""
    r = [f"# {t['id']} · {t['name']}", "", f"**Tier {TIER[t['id']]}** · {'low-voltage electronics' if t['kind']=='electronic' else 'laser-cut'} · prototype Rs {p} · price Rs {t['price']}. Status: designed and verified as far as a computer can; **no prototype built, nothing field-tested.**", "", "## Problem", t["problem"], "", "## How it works", t["how"], "", "## What I verified (and what I did not)", t["verified"], ""]
    if t["kind"] == "electronic":
        r += ["## Firmware and electronics", f"Engine `firmware/lib/utilcore.c` (`{t['engine']}`), demo build `firmware/release/{t['hex']}`. Nano pins: {t['pins']} (wiring notes in the header of `firmware/src/main_util.cpp`). Low voltage only. A custom PCB is **not laid out**; the Nano demo and the pin map above are the starting point for the EMS.", "", f"Enclosure: `enclosure_body.stl` / `enclosure_lid.stl` ({t['box'][0]}×{t['box'][1]}×{t['box'][2]} mm, 2.4 mm walls, {'watertight' if wt else 'CHECK MESH'}): a simple prototype shell; production tooling needs a proper design.", "", f"End-of-line test: {EOL[t['id']]}", ""]
    else:
        r += ["## Manufacturing files", f"`../out/{t['slug'].replace('-', '_') if t['slug']!='masala-rack' else 'masala_rack'}.svg` and `.dxf` (CUT layer = through cuts, ENGRAVE layer = marks). Generated by `../sims/sim_{'rack' if t['id']=='09' else 'stand'}.py`; results in `../docs/results_{'rack' if t['id']=='09' else 'stand'}.md`.", ""]
    r += ([f"## PCB (rev A, first draft)", f"See `../pcb/README.md`; files in `../pcb/release/{ {'01': 'seeti', '04': 'bijli', '07': 'rain'}[t['id']] }/`." , ""] if t["id"] in ("01", "04", "07") else [])
    r += [f"## Prototype budget (Rs {p}, limit Rs 3,000)", "| Item | Rs |", "|---|---|"] + [f"| {n} | {v} |" for n, v in t["proto"]] + [f"| **Total** | **{p}** |", "", f"## Designed production BOM (~2,000 units, estimate Rs {b})", "| Item | Rs |", "|---|---|"] + [f"| {n} | {v} |" for n, v in t["bom"]]
    r += ["", f"## Economics (marketplace, GST {int(t['gst']*100)} % assumed)", f"Price Rs {t['price']} → contribution Rs {c:,.0f} ({m:.0%}); BOM +30 %: Rs {c3:,.0f} ({m3:.0%}).{first}", "", "## Manufacturing", t["mfg"], "RFQ: price at 500 / 1,000 / 2,000 units, MOQ, lead time, tolerance/test report, sample cost; own the files.", "", "## Compliance (to verify)", ("Battery safety, BIS requirement for any bought-in adapter, EMC, e-waste EPR, Legal Metrology labelling; no safety claims." if t["kind"] == "electronic" else "Paint/finish safety (food-contact finish for the rack), Legal Metrology labelling."), "", "## Risks", t["risk"], "", "## Next steps", "Build the prototype from the budget → test with 5 users → adjust → RFQ.", ""]
    open(os.path.join(d, "README.md"), "w").write("\n".join(r))
    idx.append(f"| {t['id']} | [{t['name']}]({t['id']}-{t['slug']}/README.md) | {TIER[t['id']]} | {p} | {b} | {t['price']} | {c:,.0f} ({m:.0%}) | {c3:,.0f} ({m3:.0%}) |")
    rows.append([t["id"], t["name"], TIER[t["id"]], p, b, t["price"], round(c), round(m, 3), round(c3), round(m3, 3)])
with open(os.path.join(ROOT, "docs", "economics.csv"), "w", newline="") as f:
    w = csv.writer(f); w.writerow(["id", "name", "tier", "prototype_rs", "designed_bom_rs", "price_rs", "contribution_rs", "margin", "contribution_bom_plus30", "margin_bom_plus30"]); w.writerows(rows)
open(os.path.join(ROOT, "README.md"), "w").write("""# Ten utility tools (2026-10-31)

Smart, simple tools for Indian homes. Eight are low-voltage electronics (one C library of tested engines, `firmware/`), two are laser-cut (`sims/`, `out/`). Prototype ≤ Rs 3,000 each. **Nothing is built or field-tested.** First-draft PCBs (KiCad schematic, layout, Gerbers, BOM) exist for the three electronic Tier A tools in `pcb/` — software-checked only, engineer review required.

| # | Tool | Tier | Prototype Rs | BOM Rs | Price Rs | Contribution Rs | If BOM +30 % |
|---|---|---|---|---|---|---|---|
""" + "\n".join(idx) + """

**Tier A = launch first** (margin holds at +30 % BOM): Masala Rack, Laptop Stand, Seeti Counter, Bijli Meter Reader, Rain Alert Bell. **Tier B = conditional** (thin margin or price risk against cheap rivals): Tap Litre Meter, Bijli Log, Chulha Timers, Gas Taraju, Fridge Door Guard — build only after Tier A sells, or redesign to cost.

## Research notes (web search, 2026-10-31; sources are blogs/listings, treat as directional)
- Induction cooktops with automatic whistle counters exist (Prestige PIC series) — the retrofit gap for ordinary cookers is open; I found no standalone counter listed.
- LPG: magnetic strip level gauges are the cheap option and approximate; dealer weighing scales are about Rs 1,300 (IndiaMART) and B2B.
- Inverters from V-Guard/Luminous already include battery top-up reminders, so I dropped an inverter-battery monitor from the list.
- Meter pulse LEDs: constants vary by meter (1000/1600/3200 imp/kWh seen); BSES spec leaves the constant to the maker — the product asks the user to enter it from the label.
- Electricity tariffs rising and "home upgrade" demand growth reported for the 2026 festival season; no reliable category sales data was available for utility gadgets, so demand is unproven.

## Verification
110 automated checks across the eight engines with sanitizers on (`make test` in `firmware/`), eight Nano builds (`make hex`, 3–7 kB each). Real bugs found: the gas scale's sample history froze after 255 samples (fixed); the first test harness detected a tone at the generated frequency instead of the whistle frequency (test bug, fixed); first prices of five tools lost money or were thin, and were raised. Honest limits are in each README: whistle detection fails when the mic is far from the whistle, the stand slides under a hard 15 N shove, bill slab rates are placeholders.
""")
print("\n".join(idx))
